package kr.co.farmerflood.trigger.provider.mock;
import java.time.Instant; import kr.co.farmerflood.trigger.config.AppProperties; import kr.co.farmerflood.trigger.domain.*; import kr.co.farmerflood.trigger.provider.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="app.provider-mode",havingValue="mock",matchIfMissing=true)
public class MockProviders implements WaterLevelProvider,WeatherForecastProvider { private final MockScenarioStore store; public MockProviders(MockScenarioStore s){store=s;} public WaterLevelObservation latest(AppProperties.Location l){var s=store.get();return new WaterLevelObservation(l.getStationCode(),l.getStationName(),s.waterLevelMeters(),s.riskLevel(),s.updatedAt());} public RainfallTimeline timeline(int nx,int ny,int h){var s=store.get();return new RainfallTimeline(nx,ny,h,Instant.now(),s.rainfallMm(),java.util.List.of(new HourlyRainfall(Instant.now().plusSeconds(3600),s.rainfallMm()+"mm",s.rainfallMm())));} }
